def transform(grid):
    h=len(grid); w=len(grid[0]); seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append(cells)
    if not objects: return [row[:] for row in grid]
    cells=max(objects,key=lambda a:max(y for y,x in a))
    top=min(y for y,x in cells); bottom=max(y for y,x in cells)
    left=min(x for y,x in cells); right=max(x for y,x in cells)
    return [row[left:right+1] for row in grid[top:bottom+1]]

